            || (incoming_range == 2 && (byte & 0x20) != 0)
            || (incoming_range == 3 && (byte & 0x10) == 0)
            || (incoming_range == 4 && (byte & 0x10) != 0))) {
      return false;
    }
  }
  index += pending;
  if (index == length) {
    return true;
  }
  return validate_utf8_scalar((const char *)(bytes + index), length - index);
}

